<script>(()=>{document.querySelector('[data-n503-category]')?.addEventListener('click',e=>e.currentTarget.closest('.n503-category-menu')?.classList.toggle('is-open'));const nav=document.querySelector('[data-n503-nav]');document.querySelector('[data-n503-menu]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));document.querySelectorAll('[data-n503-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-n503-slide]')];if(slides.length<2)return;let i=0;setInterval(()=>{slides[i].classList.remove('is-active');i=(i+1)%slides.length;slides[i].classList.add('is-active')},Math.max(2500,Number(slider.dataset.autoplay||6000)))})})();</script>
